(function(){
'use strict';
var avatarSrc='';
function loadAvatar(){fetch('/static/ariella-avatar-runtime-20260913.js?avatar_source=header-v2',{cache:'no-store'}).then(r=>r.text()).then(js=>{var m=js.match(/const\s+src\s*=\s*'([^']+)'/);if(m&&m[1]){avatarSrc=m[1];apply();}}).catch(()=>{});}
function apply(){var chat=document.getElementById('ariellaDesktopChat');if(!chat)return;var title=chat.querySelector('.ac-head-copy strong');if(title)title.textContent='אריאלה — סוכנת הנסיעות האישית שלך';chat.querySelectorAll('.ac-avatar,.ac-mini-avatar').forEach(el=>{if(!avatarSrc)return;el.textContent='';el.style.setProperty('background-image','url("'+avatarSrc+'")','important');el.style.setProperty('background-position','center 35%','important');el.style.setProperty('background-size','115% auto','important');el.style.setProperty('background-repeat','no-repeat','important');el.style.setProperty('border-radius','50%','important');el.style.setProperty('overflow','hidden','important');});}
function boot(){var s=document.createElement('style');s.id='ariella-header-polish-v2';s.textContent='#ariellaDesktopChat .ac-head-copy{min-width:0!important;flex:1!important}#ariellaDesktopChat .ac-head-copy strong{white-space:nowrap!important}@media(max-width:899px){#ariellaDesktopChat .ac-head{padding:10px 12px!important;gap:9px!important;min-height:70px!important}#ariellaDesktopChat .ac-avatar{width:52px!important;height:52px!important;flex:0 0 52px!important}#ariellaDesktopChat .ac-head-copy strong{font-size:16px!important;line-height:1.2!important;letter-spacing:-.25px!important}#ariellaDesktopChat .ac-online{display:none!important}}@media(max-width:380px){#ariellaDesktopChat .ac-head-copy strong{font-size:14.5px!important}#ariellaDesktopChat .ac-avatar{width:48px!important;height:48px!important;flex-basis:48px!important}}';document.head.appendChild(s);loadAvatar();apply();var chat=document.getElementById('ariellaDesktopChat');if(chat)new MutationObserver(apply).observe(chat,{childList:true,subtree:true});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();